use imageable_tile_grid::{ CharTile, MultiTile, Tile, TileGrid };

#[derive(Clone, Copy)]
enum DigitTile {
    Top(u8), Bottom(u8), Empty
}
impl Tile for DigitTile {
    const SIZE: usize = 4;
    fn atlas_pos(&self) -> [usize; 2] {
        match self {
            Self::Top(n) => [ *n as usize, 0 ],
            Self::Bottom(n) => [ *n as usize, 1 ],
            Self::Empty => [ 10, 0 ],
        }
    }
}

enum TallDigit {
    N(u8), Empty
}
impl CharTile for TallDigit {
    fn from_char(c: char) -> Self {
        match c {
            ' ' => Self::Empty,
            nc if nc.is_ascii_digit() => Self::N(nc as u8 - b'0'),
            _ => panic!("invalid char"),
        }
    }
}
impl MultiTile for TallDigit {
    type SubTile = DigitTile;
    fn dimensions(&self) -> [ usize; 2 ] {
        [ 1, 2 ]
    }
    fn sub(&self, x: usize, y: usize) -> Self::SubTile {
        assert_eq!(x, 0);
        match self {
            Self::N(n) => match y {
                0 => DigitTile::Top(*n),
                1 => DigitTile::Bottom(*n),
                _ => panic!("invalid index"),
            },
            Self::Empty => DigitTile::Empty,
        }
    }
}

